#!/usr/bin/env python3
"""
Round 219o (culprits), 17 October 2026. Needs round 218o.

The Rape row's note, with the counts after the wider search of registries.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 219o (17 October)\n\nNeeds round 218o (guards on its heading). No tiles patch. No app.js?v= bump.\nThe owner\'s rape.html in the maps repo is replaced by the 17 October build.\n\n- The rape_registries note now gives the final counts: 102 national\n  registries and child-work vetting schemes outside the US, 545 US county\n  sheriffs and city police (526 from the OffenderWatch state pages the owner\n  saved for AL, IL, IN, LA, OH, WA and WY), 107 sub-national registries\n  elsewhere, 63 countries a source says have none, 77 links shown inside the\n  map. Every other country was searched in its own languages; its box lists\n  the searches.\n- rape.html (maps repo): folding panels, zoom and World buttons, all layers\n  on, DR Congo provinces with their own shading menu, links labelled registry,\n  law, official page or news.\n- Tests: one block before "round 218o" in map/test.mjs.\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round219o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 218o" not in h.read_text(encoding="utf-8"):
        sys.exit("round219o: round 218o must be applied first (round218o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round219o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json", check=False)
            sys.exit("round219o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round219o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
